 outputKey: string) =>\n    computed<readonly string[]>(() => {\n      const upstream = upstreamImages(inputName)\n      return upstream.length ? upstream : savedImages(outputKey)\n    })\n\n  return {\n    beforeImages: sideImages(BEFORE_INPUT, BEFORE_OUTPUT),\n    afterImages: sideImages(AFTER_INPUT, AFTER_OUTPUT)\n  }\n}\n","<template>\n  <div v-if=\"count > 1\" class=\"flex items-center gap-1\">\n    <span class=\"mr-1 text-muted-foreground\">\n      <slot name=\"label\" />\n    </span>\n    <Button\n      variant=\"muted-textonly\"\n      size=\"icon-sm\"\n      :disabled=\"index === 0\"\n      data-testid=\"batch-prev\"\n      @click=\"index--\"\n    >\n      <i class=\"icon-[lucide--chevron-left]\" />\n    </Button>\n    <span data-testid=\"batch-counter\">\n      {{ $t('batch.index', { current: index + 1, total: count }) }}\n    </span>\n    <Button\n      variant=\"muted-textonly\"\n      size=\"icon-sm\"\n      :disabled=\"index === count - 1\"\n      data-testid=\"batch-next\"\n      @click=\"index++\"\n    >\n      <i class=\"icon-[lucide--chevron-right]\" />\n    </Button>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\n\nconst index = defineModel<number>({ required: true })\n\ndefineProps<{\n  count: number\n}>()\n</script>\n","<template>\n  <div v-if=\"count > 1\" class=\"flex items-center gap-1\">\n    <span class=\"mr-1 text-muted-foreground\">\n      <slot name=\"label\" />\n    </span>\n    <Button\n      variant=\"muted-textonly\"\n      size=\"icon-sm\"\n      :disabled=\"index === 0\"\n      data-testid=\"batch-prev\"\n      @click=\"index--\"\n    >\n      <i class=\"icon-[lucide--chevron-left]\" />\n    </Button>\n    <span data-testid=\"batch-counter\">\n      {{ $t('batch.index', { current: index + 1, total: count }) }}\n    </span>\n    <Button\n      variant=\"muted-textonly\"\n      size=\"icon-sm\"\n      :disabled=\"index === count - 1\"\n      data-testid=\"batch-next\"\n  